#include "reviewed-collision_scheduler.hpp"
#include <cfenv>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace raikou::pic_collisions;
int checks=0;void test(bool ok,const char*text){++checks;if(!ok)throw Error(text);}template<class F>void rejects(F f,const char*text){bool rejected=false;try{f();}catch(const Error&){rejected=true;}test(rejected,text);}
int main(int argc,char**argv){try{require(argc==2,"weights input");const std::string H(64,'a'),K(64,'b');constexpr double me=9.1093837139e-31,mn=2.9915e-26;Packet p{"p","e",1,2,me,{1e7,0,0}},n{"n","H2O",1,8,mn,{0,0,0}};Cell cell{1,1e-12};Channel ch{"c","e","H2O",H,K,Observable::ExclusiveEvent,[](double){return 1e-20;}};Clock clock{1,2,10,11,H,H,H,10.5,0};auto rows=candidates({p},{n},{cell},{ch});Scheduler s(90);auto saved=s.checkpoint();
 auto bad=rows;bad[0].target_before=10;rejects([&]{s.prepare(clock,bad);},"tampered before count");bad=rows;bad[0].event_weight=1;rejects([&]{s.prepare(clock,bad);},"tampered consumed count");bad=rows;bad[0].target_remainder.low=std::numeric_limits<double>::denorm_min();rejects([&]{s.prepare(clock,bad);},"tampered remainder low");bad=rows;bad[0].target_remainder.high=7;rejects([&]{s.prepare(clock,bad);},"tampered remainder high");bad=rows;bad[0].rate_s*=2;rejects([&]{s.prepare(clock,bad);},"tampered propensity");test(s.checkpoint()==saved,"failed preparation never advances RNG");
 int queries=0;auto c1=ch,c2=ch;c2.id="c2";c1.sigma_m2=c2.sigma_m2=[&](double){++queries;return 1e-20;};rejects([&]{candidates({p},{n},{cell},{c1},0,100,100);},"pair budget zero");test(queries==0,"pair cap before query");rejects([&]{candidates({p},{n},{cell},{c1},1,0,100);},"query budget zero");test(queries==0,"query cap before callback");rejects([&]{candidates({p},{n},{cell},{c1,c2},1,1,100);},"query budget one");test(queries==1,"second query not invoked");queries=0;rejects([&]{candidates({p},{n},{cell},{c1},1,1,0);},"candidate budget zero");test(queries==1,"candidate cap after permitted query before append");queries=0;rejects([&]{candidates({p},{n},{cell},{c1,c2},1,2,1);},"candidate budget one");test(queries==2,"candidate budget distinct from query budget");auto zero=c1;zero.sigma_m2=[](double){return 0.;};test(candidates({p},{n},{cell},{zero},1,1,0).empty(),"zero sigma creates no candidate allocation");auto ineligible=c1;ineligible.projectile_state="other";queries=0;test(candidates({p},{n},{cell},{ineligible},1,0,0).empty()&&queries==0,"ineligible state does not query");auto co=n;co.proper_velocity_m_s=p.proper_velocity_m_s;auto support=ch;support.sigma_m2=[&](double E){++queries;test(E==0,"comoving support queried at zero energy");return 1e-20;};queries=0;test(candidates({p},{co},{cell},{support},1,1,0).empty()&&queries==1,"zero flux does not bypass support query");support.sigma_m2=[](double)->double{throw Error("missing zero-energy support");};rejects([&]{candidates({p},{co},{cell},{support});},"zero flux unsupported energy rejected");
 for(int k=0;k<6;++k){auto c=clock;if(k==0)c.frozen_physical_stage_s=9;if(k==1)c.frozen_physical_stage_s=12;if(k==2)c.frozen_physical_stage_s=std::numeric_limits<double>::quiet_NaN();if(k==3)c.collision_elapsed_s=-1;if(k==4)c.collision_elapsed_s=1;if(k==5)c.collision_elapsed_s=std::numeric_limits<double>::quiet_NaN();rejects([&]{s.prepare(c,rows);},"invalid stage or elapsed rejected");}
 auto proposed=s.prepare(clock,rows);test(proposed.frozen_physical_stage_s()==10.5,"physical stage preserved independently");if(proposed.event())test(proposed.event_subflow_elapsed_s()>0&&proposed.event_subflow_elapsed_s()<1,"subflow time is elapsed not global");test(s.can_publish(proposed),"live pending token");std::optional<Scheduler>life;life.emplace(88);auto old=life->prepare(clock,rows);life.reset();life.emplace(99);test(!life->can_publish(old),"same address new lifetime rejects old token");auto restart=Scheduler::restore(s.checkpoint());test(!restart.can_publish(proposed),"restart creates fresh proposal lifetime");auto fresh=restart.prepare(clock,rows);test(fresh.event_subflow_elapsed_s()==proposed.event_subflow_elapsed_s(),"restart exact unpublished RNG continuation");test(s.try_publish(proposed)&&!s.try_publish(proposed),"exactly-once token");test(restart.try_publish(fresh)&&restart.checkpoint()==s.checkpoint(),"accepted RNG restart equivalence");auto elapsed=clock;elapsed.collision_elapsed_s=.5;auto empty=s.prepare(elapsed,{});test(!empty.event()&&empty.clock().collision_elapsed_s==.5&&empty.frozen_physical_stage_s()==10.5,"empty subflow retains stage and consumed interval metadata");
 // This API still accepts direct Candidate vectors with no prepare-size argument.
 auto extra=rows[0];extra.channel_id="second";auto direct=s.prepare(clock,{rows[0],extra});test(direct.total_rate_s()>rows[0].rate_s,"prepare direct-vector path has no builder budget binding");
 auto real=p;real.weight=.031334406939830223;auto neutral=n;neutral.weight=1e6;auto partial=candidates({real},{neutral},{cell},{ch});rejects([&]{partial[0].target_remainder.require_single_weight();},"representative unequal neutral conversion is explicitly refused");std::cout<<std::setprecision(17)<<"representative_count_remainder high="<<partial[0].target_remainder.high<<" low="<<partial[0].target_remainder.low<<'\n';
 // Original positive-rate underflow remains rejected.
 auto tiny=p;tiny.weight=std::numeric_limits<double>::denorm_min();auto tn=n;tn.weight=tiny.weight;auto tx=ch;tx.sigma_m2=[](double){return std::numeric_limits<double>::denorm_min();};rejects([&]{candidates({tiny},{tn},{Cell{1,1e308}},{tx});},"propensity underflow retained");
 std::ifstream input(argv[1]);std::string line;std::ofstream output("remainders.csv");output<<std::setprecision(17)<<"label,a,b,high,low,single_conversion_rejected\n";int cases=0;while(std::getline(input,line)){std::istringstream stream(line);std::string label,aa,bb;std::getline(stream,label,',');std::getline(stream,aa,',');std::getline(stream,bb,',');double a=std::strtod(aa.c_str(),nullptr),b=std::strtod(bb.c_str(),nullptr);require(std::isfinite(a)&&std::isfinite(b)&&a>=b&&b>=0,"adversarial difference domain");auto r=difference(a,b);bool rejected=false;try{auto single=r.require_single_weight();test(r.low==0&&single==r.high,"exact single-double conversion");}catch(const Error&){rejected=true;test(r.low!=0,"only nonzero residual blocks conversion");}output<<label<<','<<a<<','<<b<<','<<r.high<<','<<r.low<<','<<rejected<<'\n';++cases;}
 std::cout<<"checks="<<checks<<" remainder_cases="<<cases<<" rounding_mode="<<std::fegetround()<<" FE_TONEAREST="<<FE_TONEAREST<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
